    return {officialDivisor,personalDaily,personalDailyName,piePercent,personalBasis,balanceTitle,confirmedPending,memberCurrent,memberPeriod,memberPeriods,memberPeriodLabel,memberLoading,memberError,loadMemberHistory,pieCaption,displayModelName,newCyclePending,cyclePairLabel,cleanStartCaption,availablePercent,dailyUsage,dailyPeople,dailyPercent,joinedCount,onlineCount,syncDetail,sliderStep,billingNotice,localQuota,accountColor,confirmedUsage,pairedDevices,managedAccounts,accountChoices,secondAccount,chooseAccount,resetCause,saveReset,memberEntries,poolAccount,statsAccount,bindDevice,bindPerson,sharedEnabled,sharedBilling,poolRemaining,poolAccounts,visibleCycles,billingRows,personPercent,personLabel,accountLabel,entryLabel,bindMember,toggleCompensation,cyclePair,cyclePairCaption,sharedPreparing,displayAccount,sharedMembers,accountCards,joinProgress,joinSaved,cycleModels,cycleUnknown,pannable,historyMin,chartTarget,liveRevision,userCycle,chartEnd,liveChart,panChart,curveMode,dailyAverage,cycleBudget,theme,setTheme,snapshot,page,ready,busy,toast,selectedDevice,selectedAccount,model,user,kind,period,piePeriod,modal,textInput,capInput,pairCode,joinCode,history,historyPeriod,advanced,settingsForm,connectionForm,formDirty,lastReceipt,selectedPath,pairPending,userColor,dragging,view,settings,devices,account,selected,epoch,officialUsed,officialLeft,officialUsageColor,clockNow,refreshRemaining,models,users,trend,pie,trendColor,trendName,localDevice,updateText,accounts,pairStatus,historyRows,nav,COLORS,COLOR_NAMES,compact,timeLabel,command,host,nativeDrag,switchPage,openModal,confirm,confirmAction,saveUserSettings,beginDeviceDrag,saveCap,scanAccount,showHistory,generatePair,joinPair,copyPair,saveSettings,toggleLimit,discover,browseProgram,removePath,route,deviceConnected,deviceUsing,deviceState,usage,saveConnection,exportDiagnostics,inform};
